// ================================
// 日志映射部分：将当前未读日志填充到保持寄存器
// ================================
IF g_LogBuffer.count > 0 THEN
    // 获取当前读指针指向的日志条目
    pCurEntry := ADR(g_LogBuffer.entries[g_LogBuffer.readIdx]);
    sCurLog := pCurEntry^.sMessage;
    iLen := pCurEntry^.length;

    // 地址100：日志长度（WORD）
    arReg_data[100] := INT_TO_WORD(iLen);

    // 地址101-102：时间戳（低字，高字）
    arReg_data[101] := DWORD_TO_WORD(pCurEntry^.timestamp AND 16#FFFF);
    arReg_data[102] := DWORD_TO_WORD(SHR(pCurEntry^.timestamp, 16));

    // 清空字符串缓冲区寄存器（地址103 ~ 152，共50个WORD）
    FOR i := 103 TO 152 DO
        arReg_data[i] := 0;
    END_FOR

    // ----- 将字符串每两个字符打包成一个 WORD -----
    // 注意：你的环境中字符串索引从0开始（已验证）
    iCharIdx := 0;      // 当前字符索引（从0开始）
    iRegIdx := 103;     // 当前寄存器地址
    WHILE iCharIdx < iLen DO
        // 低字节 = 第一个字符
        wTemp := sCurLog[iCharIdx];
        iCharIdx := iCharIdx + 1;
        // 如果有下一个字符，放入高字节
        IF iCharIdx < iLen THEN
            wTemp := wTemp OR SHL(sCurLog[iCharIdx], 8);
            iCharIdx := iCharIdx + 1;
        END_IF
        arReg_data[iRegIdx] := wTemp;
        iRegIdx := iRegIdx + 1;
    END_WHILE
ELSE
    // 无未读日志，长度寄存器写0
    arReg_data[100] := 0;
END_IF

// --------------------------------
// 处理主站确认线圈（地址16）
// --------------------------------
IF arDo_data[16] THEN
    IF g_LogBuffer.count > 0 THEN
        g_LogBuffer.readIdx := (g_LogBuffer.readIdx + 1) MOD g_LogBuffer.maxSize;
        g_LogBuffer.count := g_LogBuffer.count - 1;
    END_IF
    arDo_data[16] := FALSE;
END_IF



IF isInit=FALSE THEN							

	modtcpslaveinit(en_in:=TRUE,					//Modbus TCP Slave初始化功能块使能
	xenable:=TRUE,									//使能初始化功能
	iport:=502,										//开放端口号502
	en_out=>eout,									//Modbus TCP Slave初始化功能块执行完成
	isocket=>iSocket,								//创建的socket存入变量
	uierror=>uiErr);								//Modbus TCP Slave初始化功能块执行错误信息

	IF isocket>=0 AND uiErr=0 THEN					//成功创建socket且无错误，逻辑标志置位，下周期执行ELSE
		isInit:=TRUE;	

		enCtr:=FALSE;
		ELSE                                        //等待连接成功
		modtcpslaveinit(en_in:=0,xenable:=0);	
	END_IF

ELSE


	// 循环读取电机位置
	FOR i := 1 TO GVL.AXIS_COUNT DO
		arAi_data[i] := INT_TO_WORD(REAL_TO_INT(Axes[i].ActualAngle/aAngleFactor[i]*10.0));
	END_FOR
	Move_5Axis_Sign:=arReg_data[0];


	// 循环处理前7个通道（目标角度数组）
	IF 	bfiveDOF_state =0 THEN
		FOR i := 1 TO GVL.AXIS_COUNT DO
			dwAngle := WORD_TO_INT(arReg_data[i]);      // 有符号原始值
			PlatformTargetAngle[i] := dwAngle * aAngleFactor[i];
		END_FOR

	END_IF

  // arReg_data[19] 是点动总开关位图，bit0..bit4=X/Y/Z/B/C。
  xJogMode[1] := (arReg_data[19] AND WORD#16#0001) <> WORD#0; // X
  xJogMode[2] := (arReg_data[19] AND WORD#16#0002) <> WORD#0; // Y
  xJogMode[3] := (arReg_data[19] AND WORD#16#0004) <> WORD#0; // Z
  xJogMode[4] := (arReg_data[19] AND WORD#16#0008) <> WORD#0; // B
  xJogMode[5] := (arReg_data[19] AND WORD#16#0010) <> WORD#0; // C

  // arReg_data[6..15] 是五轴点动方向命令。
  // 方向命令必须同时满足 arReg_data[19] 对应点动总开关位，避免单独残留方向寄存器导致误点动。
  xJogFwd[1] := xJogMode[1] AND (arReg_data[6] <> WORD#0);
  xJogRev[1] := xJogMode[1] AND (arReg_data[7] <> WORD#0);

  xJogFwd[2] := xJogMode[2] AND (arReg_data[8] <> WORD#0);
  xJogRev[2] := xJogMode[2] AND (arReg_data[9] <> WORD#0);

  xJogFwd[3] := xJogMode[3] AND (arReg_data[10] <> WORD#0);
  xJogRev[3] := xJogMode[3] AND (arReg_data[11] <> WORD#0);

  xJogFwd[4] := xJogMode[4] AND (arReg_data[12] <> WORD#0);
  xJogRev[4] := xJogMode[4] AND (arReg_data[13] <> WORD#0);

  xJogFwd[5] := xJogMode[5] AND (arReg_data[14] <> WORD#0);
  xJogRev[5] := xJogMode[5] AND (arReg_data[15] <> WORD#0);
	modtcpslavectrl(en_in:=enCtr,					//Modbus TCP Slave执行功能块使能
	xenable:=TRUE,									//Modbus TCP Slave执行功能使能
	isocket:=isocket,								//输入创建的socket
	dwatchdogtime:=2000,							//看门狗时间
	p_clientsocket:=ADR(arClient),					//将连接进来的socket存放到数组
	imaxclientcount:=10,							//设置最大连接数量
	uido_number:=17,uido_startaddr:=0,pdo_data:=ADR(arDo_data),		//uido_number设定线圈个数，uido_startaddr设定线圈起始地址，数据存放在arDo_data数组
	uidi_number:=16,uidi_startaddr:=0,pdi_data:=ADR(arDi_data),		//uidi_number设定离散型数据个数，uidi_startaddr设定离散型数据起始地址，数据存放在arDi_data数组
	uireg_number:=200,uireg_startaddr:=0,preg_data:=ADR(arReg_data), //uireg_number设定保持型寄存器个数，uireg_startaddr设定保持型寄存器起始地址，数据存放在arReg_data数组
	uiai_number:=16,uiai_startaddr:=0,pai_data:=ADR(arAi_data),		//uiai_number设定输入型寄存器个数，uiai_startaddr设定输入型寄存器起始地址，数据存放在arAi_data数组
	en_out=>eout,									//Modbus TCP Slave执行功能块执行完成
	uierror=>uierr);								//Modbus TCP Slave执行功能块执行错误信息
	enctr:=TRUE;
	IF uierr <>0 THEN                               //如果从站报错，则重新连接从站
		modtcpslaveinit(en_in:=0,xenable:=0);	
		isInit:=0;
	END_IF
END_IF


// 释放锁
g_LogLock := FALSE;

// 本程序只做反馈和诊断，不直接控制轴运动。
// [32] 五轴总使能命令。
// [33..37] 五轴状态字。
// [38..47] 五轴驱动 AxisErrorID，来自 MC_ReadAxisError.AxisErrorID。
// [48] 五轴 AxisEnable 请求反馈。
// [49..58] 五轴 MC_ReadStatus.ErrorID。
// [59..68] 五轴 MC_ReadAxisError.ErrorID。
// [69..78] 五轴 MC_Power.ErrorID，由各单轴程序写入。
// [79..83] 五轴 MC_Power 诊断字，bit0=Status，bit1=Error。
// [84] 诊断版本号，26084 表示 v26084 诊断版已生效。
// [85] 使能请求 TRUE 但 MC_ReadStatus 仍 Disabled 的位图。
// [86] MC_ReadStatus.Error 位图。
// [87] MC_ReadAxisError.Error 位图。
// [88] MC_ReadStatus.FBErrorOccured 位图。

fbStatusX(
    Axis := AXIS_X,
    Enable := TRUE,
    Valid => ,
    Busy => ,
    Error => bStatusErrorX,
    ErrorID => eStatusErrorX,
    Disabled => ,
    Errorstop => ,
    Stopping => ,
    StandStill => ,
    DiscreteMotion => ,
    ContinuousMotion => ,
    SynchronizedMotion => ,
    Homing => ,
    ConstantVelocity => ,
    Accelerating => ,
    Decelerating => ,
    FBErrorOccured => bStatusFBErrorX,
);

// MC_ReadAxisError.AxisErrorID 只表示驱动轴本体错误号。
// 如果网线断开导致 MC_ReadAxisError 自己报 Error，错误号会写到 arReg_data[59..60]。
fbAxisErrorX(
    Axis := AXIS_X,
    Enable := TRUE,
    Valid => ,
    Busy => ,
    Error => bAxisReadErrorX,
    ErrorID => eAxisReadErrorX,
    AxisError => bAxisErrorX,
    AxisErrorID => dwAxisErrorX,
    SWEndSwitchActive => bSwEndSwitchX
);
IF NOT bAxisErrorX THEN
    // 没有驱动轴本体错误时清零 AxisErrorID，但不清零各功能块自己的 ErrorID。
    dwAxisErrorX := DWORD#0;
END_IF;

// 把 X 轴 BOOL 状态压缩成一个 WORD 状态字输出到 arReg_data[33]。
// 主状态字只放轴状态和轴本体错误，不再混入 MC_ReadStatus 功能块自己的 Error 位。
// MC_ReadStatus.ErrorID 单独放到 arReg_data[49..50]，
// MC_ReadStatus.Error 汇总位单独放到 arReg_data[86]，避免 Python 默认状态一直显示“功能块错误”。
wStatusX := WORD#0;
IF fbStatusX.Disabled THEN wStatusX := wStatusX OR WORD#16#0001; END_IF;
IF fbStatusX.Errorstop THEN wStatusX := wStatusX OR WORD#16#0002; END_IF;
IF fbStatusX.Stopping THEN wStatusX := wStatusX OR WORD#16#0004; END_IF;
IF fbStatusX.StandStill THEN wStatusX := wStatusX OR WORD#16#0008; END_IF;
IF fbStatusX.DiscreteMotion THEN wStatusX := wStatusX OR WORD#16#0010; END_IF;
IF fbStatusX.ContinuousMotion THEN wStatusX := wStatusX OR WORD#16#0020; END_IF;
IF fbStatusX.SynchronizedMotion THEN wStatusX := wStatusX OR WORD#16#0040; END_IF;
IF fbStatusX.Homing THEN wStatusX := wStatusX OR WORD#16#0080; END_IF;
IF fbStatusX.ConstantVelocity THEN wStatusX := wStatusX OR WORD#16#0100; END_IF;
IF fbStatusX.Accelerating THEN wStatusX := wStatusX OR WORD#16#0200; END_IF;
IF fbStatusX.Decelerating THEN wStatusX := wStatusX OR WORD#16#0400; END_IF;
IF bAxisErrorX THEN wStatusX := wStatusX OR WORD#16#4000; END_IF;
IF bSwEndSwitchX THEN wStatusX := wStatusX OR WORD#16#8000; END_IF;
arReg_data[33] := WORD_TO_INT(wStatusX);

// arReg_data[38..39] 保存 X 轴驱动 AxisErrorID。
arReg_data[38] := WORD_TO_INT(DWORD_TO_WORD(dwAxisErrorX));
arReg_data[39] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwAxisErrorX, 16)));

// arReg_data[49..50] 保存 X 轴 MC_ReadStatus.ErrorID。
arReg_data[49] := WORD_TO_INT(DWORD_TO_WORD(TO_DWORD(eStatusErrorX)));
arReg_data[50] := WORD_TO_INT(DWORD_TO_WORD(SHR(TO_DWORD(eStatusErrorX), 16)));

// arReg_data[59..60] 保存 X 轴 MC_ReadAxisError.ErrorID。
arReg_data[59] := WORD_TO_INT(DWORD_TO_WORD(TO_DWORD(eAxisReadErrorX)));
arReg_data[60] := WORD_TO_INT(DWORD_TO_WORD(SHR(TO_DWORD(eAxisReadErrorX), 16)));

