  xResetCmdReg := (arReg_data[89] AND WORD#16#0008) <> WORD#0;

  // 在 EtherCAT_Task 内直接解析点动总开关和方向命令。
  // 这样 Jog 程序调用 FB_ServoJog 前，拿到的是本任务内最新的寄存器状态。
  xJogMode[4] := (arReg_data[19] AND WORD#16#0008) <> WORD#0;
  xJogFwd[4] := xJogMode[4] AND (arReg_data[12] <> WORD#0);
  xJogRev[4] := xJogMode[4] AND (arReg_data[13] <> WORD#0);

  // 点动侧使能跟随 arReg_data[32] 解析后的 GVL.Axes[4].AxisEnable。
  // 五轴总关闭时，点动功能块不会继续用本地 TRUE 保持上使能。
  xServoEnable := GVL.Axes[4].AxisEnable;

  fbJogB(
      Axis := AXIS_B,
      xServoOn := xServoEnable,
      xReset := xResetCmdReg,
      xJogFwd := xJogFwd[4],
      xJogRev := xJogRev[4],
      xLimitFwd := FALSE,
      xLimitRev := FALSE,
      lrJogVel := 100.0,
      lrAcc := 100.0,
      lrDec := 200.0,
      lrJerk := 0.0
  );


  // arReg_data[90] 反馈复位命令当前是否被 PLC 读到，bit0..bit4=X/Y/Z/B/C。
  IF xResetCmdReg THEN
    arReg_data[90] := WORD_TO_INT(INT_TO_WORD(arReg_data[90]) OR WORD#16#0008);
ELSE
    arReg_data[90] := WORD_TO_INT(INT_TO_WORD(arReg_data[90]) AND WORD#16#FFF7);
END_IF;

  // arReg_data[91] 反馈点动总开关 xJogMode，bit0..bit4=X/Y/Z/B/C。
  IF xJogMode[4] THEN
    arReg_data[91] := WORD_TO_INT(INT_TO_WORD(arReg_data[91]) OR WORD#16#0008);
ELSE
    arReg_data[91] := WORD_TO_INT(INT_TO_WORD(arReg_data[91]) AND WORD#16#FFF7);
END_IF;

  // arReg_data[92] 反馈进入 FB_ServoJog 前的正向点动命令。
  IF xJogFwd[4] THEN
    arReg_data[92] := WORD_TO_INT(INT_TO_WORD(arReg_data[92]) OR WORD#16#0008);
ELSE
    arReg_data[92] := WORD_TO_INT(INT_TO_WORD(arReg_data[92]) AND WORD#16#FFF7);
END_IF;

  // arReg_data[93] 反馈进入 FB_ServoJog 前的反向点动命令。
  IF xJogRev[4] THEN
    arReg_data[93] := WORD_TO_INT(INT_TO_WORD(arReg_data[93]) OR WORD#16#0008);
ELSE
    arReg_data[93] := WORD_TO_INT(INT_TO_WORD(arReg_data[93]) AND WORD#16#FFF7);
END_IF;

  // arReg_data[94] 反馈 FB_ServoJog.xReady，TRUE 表示点动功能块内部 MC_Power 已就绪。
  IF fbJogB.xReady THEN
    arReg_data[94] := WORD_TO_INT(INT_TO_WORD(arReg_data[94]) OR WORD#16#0008);
ELSE
    arReg_data[94] := WORD_TO_INT(INT_TO_WORD(arReg_data[94]) AND WORD#16#FFF7);
END_IF;

  // arReg_data[95] 反馈 FB_ServoJog.xMoving，TRUE 表示当前轴正在点动。
  IF fbJogB.xMoving THEN
    arReg_data[95] := WORD_TO_INT(INT_TO_WORD(arReg_data[95]) OR WORD#16#0008);
ELSE
    arReg_data[95] := WORD_TO_INT(INT_TO_WORD(arReg_data[95]) AND WORD#16#FFF7);
END_IF;

  // arReg_data[96] 反馈 FB_ServoJog.xFault，TRUE 表示点动功能块检测到故障。
  IF fbJogB.xFault THEN
    arReg_data[96] := WORD_TO_INT(INT_TO_WORD(arReg_data[96]) OR WORD#16#0008);
ELSE
    arReg_data[96] := WORD_TO_INT(INT_TO_WORD(arReg_data[96]) AND WORD#16#FFF7);
END_IF;

  // arReg_data[97] 反馈 FB_ServoJog.xJogError，TRUE 表示 MC_Jog 功能块报错。
  IF fbJogB.xJogError THEN
    arReg_data[97] := WORD_TO_INT(INT_TO_WORD(arReg_data[97]) OR WORD#16#0008);
ELSE
    arReg_data[97] := WORD_TO_INT(INT_TO_WORD(arReg_data[97]) AND WORD#16#FFF7);
END_IF;

  // arReg_data[98] 反馈 FB_ServoJog.xJogAborted，TRUE 表示点动命令被中止。
  IF fbJogB.xJogAborted THEN
    arReg_data[98] := WORD_TO_INT(INT_TO_WORD(arReg_data[98]) OR WORD#16#0008);
ELSE
    arReg_data[98] := WORD_TO_INT(INT_TO_WORD(arReg_data[98]) AND WORD#16#FFF7);
END_IF;

  // arReg_data[99] 是点动/复位诊断版本号，Python 用它判断 [89..99] 是否已生效。
  arReg_data[99] := 26084;






  // ================================
  // 5轴点动控制
  // ================================


  // arReg_data[89] 是五轴复位命令位图，bit0..bit4=X/Y/Z/B/C。
  // Python 复位时写一个短脉冲；FB_ServoJog 内部用 R_TRIG 转成 MC_Reset 上升沿。
  xResetCmdReg := (arReg_data[89] AND WORD#16#0010) <> WORD#0;

  // 在 EtherCAT_Task 内直接解析点动总开关和方向命令。
  // 这样 Jog 程序调用 FB_ServoJog 前，拿到的是本任务内最新的寄存器状态。
  xJogMode[5] := (arReg_data[19] AND WORD#16#0010) <> WORD#0;
  xJogFwd[5] := xJogMode[5] AND (arReg_data[14] <> WORD#0);
  xJogRev[5] := xJogMode[5] AND (arReg_data[15] <> WORD#0);

  // 点动侧使能跟随 arReg_data[32] 解析后的 GVL.Axes[5].AxisEnable。
  // 五轴总关闭时，点动功能块不会继续用本地 TRUE 保持上使能。
  xServoEnable := GVL.Axes[5].AxisEnable;

  fbJogC(
      Axis := AXIS_C,
      xServoOn := xServoEnable,
      xReset := xResetCmdReg,
      xJogFwd := xJogFwd[5],
      xJogRev := xJogRev[5],
      xLimitFwd := FALSE,
      xLimitRev := FALSE,
      lrJogVel := 100.0,
      lrAcc := 100.0,
      lrDec := 200.0,
