  );


  // arReg_data[90] 反馈复位命令当前是否被 PLC 读到，bit0..bit4=X/Y/Z/B/C。
  IF xResetCmdReg THEN
    arReg_data[90] := WORD_TO_INT(INT_TO_WORD(arReg_data[90]) OR WORD#16#0010);
ELSE
    arReg_data[90] := WORD_TO_INT(INT_TO_WORD(arReg_data[90]) AND WORD#16#FFEF);
END_IF;

  // arReg_data[91] 反馈点动总开关 xJogMode，bit0..bit4=X/Y/Z/B/C。
  IF xJogMode[5] THEN
    arReg_data[91] := WORD_TO_INT(INT_TO_WORD(arReg_data[91]) OR WORD#16#0010);
ELSE
    arReg_data[91] := WORD_TO_INT(INT_TO_WORD(arReg_data[91]) AND WORD#16#FFEF);
END_IF;

  // arReg_data[92] 反馈进入 FB_ServoJog 前的正向点动命令。
  IF xJogFwd[5] THEN
    arReg_data[92] := WORD_TO_INT(INT_TO_WORD(arReg_data[92]) OR WORD#16#0010);
ELSE
    arReg_data[92] := WORD_TO_INT(INT_TO_WORD(arReg_data[92]) AND WORD#16#FFEF);
END_IF;

  // arReg_data[93] 反馈进入 FB_ServoJog 前的反向点动命令。
  IF xJogRev[5] THEN
    arReg_data[93] := WORD_TO_INT(INT_TO_WORD(arReg_data[93]) OR WORD#16#0010);
ELSE
    arReg_data[93] := WORD_TO_INT(INT_TO_WORD(arReg_data[93]) AND WORD#16#FFEF);
END_IF;

  // arReg_data[94] 反馈 FB_ServoJog.xReady，TRUE 表示点动功能块内部 MC_Power 已就绪。
  IF fbJogC.xReady THEN
    arReg_data[94] := WORD_TO_INT(INT_TO_WORD(arReg_data[94]) OR WORD#16#0010);
ELSE
    arReg_data[94] := WORD_TO_INT(INT_TO_WORD(arReg_data[94]) AND WORD#16#FFEF);
END_IF;

  // arReg_data[95] 反馈 FB_ServoJog.xMoving，TRUE 表示当前轴正在点动。
  IF fbJogC.xMoving THEN
    arReg_data[95] := WORD_TO_INT(INT_TO_WORD(arReg_data[95]) OR WORD#16#0010);
ELSE
    arReg_data[95] := WORD_TO_INT(INT_TO_WORD(arReg_data[95]) AND WORD#16#FFEF);
END_IF;

  // arReg_data[96] 反馈 FB_ServoJog.xFault，TRUE 表示点动功能块检测到故障。
  IF fbJogC.xFault THEN
    arReg_data[96] := WORD_TO_INT(INT_TO_WORD(arReg_data[96]) OR WORD#16#0010);
ELSE
    arReg_data[96] := WORD_TO_INT(INT_TO_WORD(arReg_data[96]) AND WORD#16#FFEF);
END_IF;

  // arReg_data[97] 反馈 FB_ServoJog.xJogError，TRUE 表示 MC_Jog 功能块报错。
  IF fbJogC.xJogError THEN
    arReg_data[97] := WORD_TO_INT(INT_TO_WORD(arReg_data[97]) OR WORD#16#0010);
ELSE
    arReg_data[97] := WORD_TO_INT(INT_TO_WORD(arReg_data[97]) AND WORD#16#FFEF);
END_IF;

  // arReg_data[98] 反馈 FB_ServoJog.xJogAborted，TRUE 表示点动命令被中止。
  IF fbJogC.xJogAborted THEN
    arReg_data[98] := WORD_TO_INT(INT_TO_WORD(arReg_data[98]) OR WORD#16#0010);
ELSE
    arReg_data[98] := WORD_TO_INT(INT_TO_WORD(arReg_data[98]) AND WORD#16#FFEF);
END_IF;

  // arReg_data[99] 是点动/复位诊断版本号，Python 用它判断 [89..99] 是否已生效。
  arReg_data[99] := 26084;
